class Solution { static const long long MOD=1000000007LL;long long power(long long base,long long exponent){long long result=1;while(exponent){if(exponent&1)result=result*base%MOD;base=base*base%MOD;exponent>>=1;}return result;}public:int numberOfSequence(int n,vector<int>& sick){int healthy=n-sick.size();vector<long long> factorial(healthy+1),inverse(healthy+1);factorial[0]=1;for(int i=1;i<=healthy;++i)factorial[i]=factorial[i-1]*i%MOD;inverse[healthy]=power(factorial[healthy],MOD-2);for(int i=healthy;i>0;--i)inverse[i-1]=inverse[i]*i%MOD;long long answer=factorial[healthy];int left=sick[0],right=n-1-sick.back();answer=answer*inverse[left]%MOD*inverse[right]%MOD;for(int i=1;i<(int)sick.size();++i){int gap=sick[i]-sick[i-1]-1;answer=answer*inverse[gap]%MOD;if(gap>0)answer=answer*power(2,gap-1)%MOD;}return answer;} };
